lib/actions.sh.text:
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?_action=name).
# The key must stay within A-Za-z0-9_.- : a Cirrus function URL answers 400 InvalidQueryStringKey otherwise (EVT-412).
action_url() { echo "?_action=$1"; }
# Prints the action named by a query string, or nothing.
# Also accepts the legacy form "?/name" (pages already served, requests via the CDN).
action_from_query() {
  local q=$1 p
  case "$q" in /*) q=${q#/}; echo "${q%%&*}"; return ;; esac
  local IFS='&'
  for p in $q; do case "$p" in _action=*) echo "${p#_action=}"; return ;; esac; done
}

