# EVT-412: function URL rejects query keys outside A-Za-z0-9_.- ; forms must use a valid key
bash bin/render event | grep -o 'action="[^"]*"' | grep -q '^action="?[A-Za-z0-9_.-]*=' || { echo "render key"; fail=1; }
bash bin/handle POST '/events/1/edit?_action=save' | grep -q '^200 save' || { echo "handle new"; fail=1; }
bash bin/handle POST '/events/1/edit?x=1&_action=save' | grep -q '^200 save' || { echo "handle multi"; fail=1; }
bash bin/handle POST '/events/1/edit?_action=nope' | grep -q '^404' || { echo "handle unknown"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle legacy"; fail=1; }
