# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must use only A-Za-z0-9_.- (Cirrus function URLs reject other keys, e.g. "/save").
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing. The legacy form (?/name) is still read.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; /*) echo "${1#/}" ;; esac; }

tests/forms_test.sh.text:
#!/bin/bash
fail=0
out=$(bash bin/render event)
echo "$out" | grep -q 'action=' || { echo "render"; fail=1; }
# every rendered action's query key must be valid for a Cirrus function URL
for u in $(echo "$out" | grep -o 'action="[^"]*"' | sed 's/action="//;s/"$//'); do
  key=${u#\?}; key=${key%%=*}
  [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $key"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle legacy"; fail=1; }
bash bin/handle POST '/events/1/edit?action=nope' | grep -q '^404' || { echo "handle unknown"; fail=1; }
exit $fail
